        this.menuPage = 'main';
        try { if (this._instr) this.hideInstrucciones(true); } catch (eHs) { /* */ }
        if (this.goHomeHall()) {
          if (!this.menuOpen) this.toggleMenu();
          else { this.anchorMenu(); this.drawMenu(); }
        }
        break;
